import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.a6FUKr6c.js";const h=JSON.parse('{"title":"@chamvi/tool-files","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tool-files.md","filePath":"reference/tool-files.md","lastUpdated":1794387542000}'),n={name:"reference/tool-files.md"};function c(r,e,l,i,d,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="chamvi-tool-files" tabindex="-1">@chamvi/tool-files <a class="header-anchor" href="#chamvi-tool-files" aria-label="Permalink to &quot;@chamvi/tool-files&quot;">​</a></h1><p>In-memory JSON, CSV and text processing over run artifacts for chamvi agents. ESM only, Node.js <code>&gt;=26.0.0</code>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#DCE9F2;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/tool-files</span><span style="color:#E7C58C;"> @chamvi/core</span><span style="color:#E7C58C;"> ai</span><span style="color:#E7C58C;"> --save</span></span></code></pre></div><p><code>@chamvi/core</code> and <code>ai</code> are peer dependencies. See <a href="/guide/tools#file-processing-tools">File processing tools</a> for a model-agent example, or the <a href="https://github.com/chamvi/chamvi/blob/master/packages/tool-files/test/fixtures/readme-example.ts" target="_blank" rel="noreferrer">executable model-free example</a>.</p><h2 id="filetools" tabindex="-1">fileTools <a class="header-anchor" href="#filetools" aria-label="Permalink to &quot;fileTools&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">function</span><span style="color:#DCE9F2;"> fileTools(options?: FileToolsOptions): {</span></span>
<span class="line"><span style="color:#DCE9F2;">    list_artifacts: Tool&lt;ListArtifactsInput, ListArtifactsResult&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">    process_files: Tool&lt;ProcessFilesInput, ProcessFilesResult&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> FILES_MAX_BYTES: </span><span style="color:#E7C58C;">5_242_880</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> FILES_MAX_FILES: </span><span style="color:#E7C58C;">16</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> FILES_TIMEOUT_MS: </span><span style="color:#E7C58C;">30_000</span><span style="color:#DCE9F2;">;</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> FileToolsOptions = { maxBytes?: number; timeoutMs?: number };</span></span></code></pre></div><p><code>maxBytes</code> accepts integers <code>1..16_777_216</code>; <code>timeoutMs</code> accepts integers <code>1..2_147_483_647</code>. Invalid options raise <code>InvalidAgentDefinitionError</code> at factory creation. There is no runtime, network or custom-command configuration.</p><h2 id="list-artifacts" tabindex="-1">list_artifacts <a class="header-anchor" href="#list-artifacts" aria-label="Permalink to &quot;list_artifacts&quot;">​</a></h2><p>Returns up to 16 native current-run <code>Artifact</code> metadata objects without loading bytes. <code>offset</code> defaults to <code>0</code> and must be a nonnegative safe integer. Pass <code>nextOffset</code> as <code>offset</code> to continue; an empty or out-of-range page has no cursor. Model-visible attachment content does not carry artifact IDs, so discover them here before selecting inputs.</p><h2 id="process-files" tabindex="-1">process_files <a class="header-anchor" href="#process-files" aria-label="Permalink to &quot;process_files&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#7F95A6;">/*</span></span>
<span class="line"><span style="color:#7F95A6;"> * Copyright (c) 2026.</span></span>
<span class="line"><span style="color:#7F95A6;"> * Author Peter Placzek (tada5hi)</span></span>
<span class="line"><span style="color:#7F95A6;"> * For the full copyright and license information,</span></span>
<span class="line"><span style="color:#7F95A6;"> * view the LICENSE file that was distributed with this source code.</span></span>
<span class="line"><span style="color:#7F95A6;"> */</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">import</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> { Artifact } </span><span style="color:#8FD0F2;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/core&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> ProcessFilesInput = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    command: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    inputs?: Array&lt;{ artifactId: string; path: string }&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">    outputs?: Array&lt;{ path: string; mediaType: string }&gt;;</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> ProcessFilesResult = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    exitCode: number;</span></span>
<span class="line"><span style="color:#DCE9F2;">    stdout: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    stderr: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    artifacts: Artifact[];</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> ListArtifactsInput = { offset?: number };</span></span>
<span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> type</span><span style="color:#DCE9F2;"> ListArtifactsResult = { artifacts: Artifact[]; nextOffset?: number };</span></span></code></pre></div><p>Each call creates a fresh in-memory filesystem, environment and cwd <code>/workspace</code>. <code>inputs</code> maps selected current-run artifact IDs to relative paths; <code>outputs</code> selects files to publish as native run artifacts. Both lists default to empty, at most 16 items each. No unrelated artifacts, host files or previous call state are imported. Pass a returned artifact ID explicitly to a later call to retain a file. Unselected files disappear after the call.</p><p>Paths name relative POSIX files of at most 255 UTF-8 bytes: no absolute paths, <code>..</code> components, backslashes, control characters or directory-only paths. Harmless <code>.</code> and repeated separators normalize; duplicate normalized paths within a selection are refused. An output may name an input path. Media types are <code>type/subtype</code> without parameters.</p><p>Each selected output must be a regular file and the complete output selection must fit the byte bound before any publication. Raw output bytes are preserved. Returned <code>Artifact</code> metadata is the existing core type, usable with <code>ctx.artifacts.get(id)</code> and existing artifact-aware tools. No channel delivery happens automatically. See <a href="/reference/#artifacts">Artifacts</a>.</p><h2 id="commands-and-limits" tabindex="-1">Commands and limits <a class="header-anchor" href="#commands-and-limits" aria-label="Permalink to &quot;Commands and limits&quot;">​</a></h2><p>Supported commands: <code>awk</code>, <code>base64</code>, <code>basename</code>, <code>cat</code>, <code>column</code>, <code>comm</code>, <code>cp</code>, <code>cut</code>, <code>diff</code>, <code>dirname</code>, <code>echo</code>, <code>env</code>, <code>expand</code>, <code>find</code>, <code>fold</code>, <code>grep</code>, <code>head</code>, <code>help</code>, <code>join</code>, <code>jq</code>, <code>ls</code>, <code>mkdir</code>, <code>mv</code>, <code>nl</code>, <code>paste</code>, <code>printf</code>, <code>pwd</code>, <code>rev</code>, <code>rg</code>, <code>rm</code>, <code>rmdir</code>, <code>sed</code>, <code>seq</code>, <code>sort</code>, <code>split</code>, <code>tail</code>, <code>tee</code>, <code>touch</code>, <code>tr</code>, <code>uniq</code>, <code>wc</code>, <code>xan</code>, <code>xargs</code>, <code>yq</code>. Interpreter shell syntax and builtins remain available.</p><table tabindex="0"><thead><tr><th>Bound</th><th>Value</th></tr></thead><tbody><tr><td>Aggregate input bytes</td><td><code>maxBytes</code>, default 5 MiB</td></tr><tr><td>Aggregate selected output bytes</td><td>Independently <code>maxBytes</code></td></tr><tr><td>Command source</td><td>16,384 UTF-8 bytes</td></tr><tr><td>Decoded stdout and stderr together</td><td>65,536 UTF-8 bytes, stderr retained first; clipping includes <code>[output truncated]</code> within the cap</td></tr><tr><td>Cumulative interpreter work output</td><td><code>max(65_536, maxBytes * 4)</code> bytes, including output before redirection</td></tr><tr><td>Execution deadline</td><td><code>timeoutMs</code>, default 30 seconds, interpreter execution only; the thread is ended 2 seconds later</td></tr><tr><td>Interpreter heap</td><td>512 MiB; exceeding it exits 137</td></tr><tr><td>Scratch filesystem including synthetic files</td><td><code>65_536 + maxBytes * 2</code> bytes</td></tr></tbody></table><p>The interpreter uses the hardened execution profile, with loop, command and record budgets raised to 1,000,000 to suit the byte limit. Successful commands can return clipped diagnostics. The additive scratch reserve accommodates synthetic command/proc files alongside full selected input/output room; artifact caps remain exact. Work and scratch budgets stay finite, so arbitrarily long pipelines or intermediate expansion can exhaust them.</p><p>Networking, custom commands, Python, JavaScript, SQL, archive commands and host executables are unavailable. The interpreter runs on a worker thread, ended at <code>timeoutMs</code> plus 2 seconds (exit 124) or above 512 MiB of heap (exit 137), so a stuck command cannot stall the host&#39;s event loop. A thread has no VM isolation or complete host-security boundary. Docker and Kubernetes remain the <a href="/guide/workspaces">coding workspace</a> choices for Git, installing dependencies, builds, tests and servers.</p><h2 id="errors-and-cancellation" tabindex="-1">Errors and cancellation <a class="header-anchor" href="#errors-and-cancellation" aria-label="Permalink to &quot;Errors and cancellation&quot;">​</a></h2><p>Nonzero interpreter exits return bounded diagnostics with <code>artifacts: []</code>. Invalid selections, foreign-run IDs, invalid output files or size overflow raise <code>ValidationError</code> before publishing any outputs. Unexpected interpreter infrastructure failures raise <code>SandboxError</code>; artifact/store errors propagate unchanged. Model agents see tool errors; an unhandled error in a simple agent fails its run.</p><p>Run cancellation and SDK abort preserve the original reason. Cancellation stops further puts once observed, but successful puts remain. Store writes are not a transaction: an infrastructure failure or cancellation can leave already-published artifacts.</p><h2 id="identity-replay-and-trust" tabindex="-1">Identity, replay and trust <a class="header-anchor" href="#identity-replay-and-trust" aria-label="Permalink to &quot;Identity, replay and trust&quot;">​</a></h2><p>Output filenames are normalized relative paths. The key is <code>process_files:</code> plus SHA-256 of JSON <code>[toolCallKey(ctx), normalizedPath]</code> (the core key includes run, step and call identity). The same call replay replaces its own artifact IDs; separate calls with the same output path retain separate artifacts, protecting earlier checkpoints.</p><p>These are plain computation tools, not effect tools. Simple-agent approval replay can rerun computation, which is neither exactly-once nor necessarily deterministic. Completed model-agent steps resume from their checkpoint without repeating that processing step. Both tools declare <code>trust: { taint: true }</code>; file content and results are untrusted data. Existing <a href="/guide/tools#untrusted-content-and-outbound-tools">outbound gates</a> apply to later outbound operations.</p>`,26)])])}const m=t(n,[["render",c]]);export{h as __pageData,m as default};
